og", "categoria": "logistica", "descricao": "Transportadora nacional", "cor": "#E30613", "icone": "https://cdn.simpleicons.org/dhl/E30613", "campos": ["cnpj", "token"], "conectado": false, "status": "nao_configurado"}, {"tipo": "loggi", "nome": "Loggi", "categoria": "logistica", "descricao": "Entregas e logística urbana", "cor": "#000000", "icone": "https://cdn.simpleicons.org/logitech/000000", "campos": ["client_id", "client_secret", "access_token"], "conectado": false, "status": "nao_configurado"}, {"tipo": "azul_cargo", "nome": "Azul Cargo", "categoria": "logistica", "descricao": "Transporte aéreo de cargas", "cor": "#005DAA", "icone": "https://cdn.simpleicons.org/americanairlines/005DAA", "campos": ["codigo_cliente", "token"], "conectado": false, "status": "nao_configurado"}, {"tipo": "google_ads", "nome": "Google Ads", "categoria": "marketing", "descricao": "Campanhas e conversões Google Ads", "cor": "#4285F4", "icone": "https://cdn.simpleicons.org/googleads/4285F4", "campos": ["developer_token", "client_id", "client_secret", "refresh_token", "customer_id"], "conectado": false, "status": "nao_configurado"}, {"tipo": "meta_ads", "nome": "Meta Ads", "categoria": "marketing", "descricao": "Facebook e Instagram Ads", "cor": "#0866FF", "icone": "https://cdn.simpleicons.org/meta/0866FF", "campos": ["business_id", "ad_account_id", "access_token"], "conectado": false, "status": "nao_configurado"}, {"tipo": "tiktok_ads", "nome": "TikTok Ads", "categoria": "marketing", "descricao": "Campanhas no TikTok Ads", "cor": "#111111", "icone": "https://cdn.simpleicons.org/tiktok/111111", "campos": ["app_id", "secret", "access_token", "advertiser_id"], "conectado": false, "status": "nao_configurado"}, {"tipo": "mailchimp", "nome": "Mailchimp", "categoria": "marketing", "descricao": "E-mail marketing e automação", "cor": "#FFE01B", "icone": "https://cdn.simpleicons.org/mailchimp/FFE01B", "campos": ["api_key", "server_prefix"], "conectado": false, "status": "nao_configurado"}, {"tipo": "rd_station", "nome": "RD Station", "categoria": "marketing", "descricao": "Marketing e CRM RD Station", "cor": "#5B2EFF", "icone": "https://cdn.simpleicons.org/hubspot/5B2EFF", "campos": ["client_id", "client_secret", "access_token", "refresh_token"], "conectado": false, "status": "nao_configurado"}, {"tipo": "hubspot", "nome": "HubSpot", "categoria": "marketing", "descricao": "CRM, marketing e atendimento", "cor": "#FF7A59", "icone": "https://cdn.simpleicons.org/hubspot/FF7A59", "campos": ["client_id", "client_secret", "access_token", "refresh_token"], "conectado": false, "status": "nao_configurado"}, {"tipo": "google_business", "nome": "Google Business Profile", "categoria": "marketing", "descricao": "Perfil da empresa e avaliações", "cor": "#4285F4", "icone": "https://cdn.simpleicons.org/googlemybusiness/4285F4", "campos": ["client_id", "client_secret", "refresh_token", "account_id"], "conectado": false, "status": "nao_configurado"}]
const categoriaNomes={marketplace:'Marketplaces',ecommerce:'Lojas virtuais',erp:'ERPs e Hubs',pagamentos:'Pagamentos',logistica:'Logística',marketing:'Marketing e CRM'}
const categorias=computed(()=>Object.keys(categoriaNomes).map(id=>({id,label:categoriaNomes[id],total:conectores.value.filter(c=>c.categoria===id).length})).filter(c=>c.total))
const totalConectados=computed(()=>conectores.value.filter(c=>c.status==='ativo').length)
const filtrados=computed(()=>{let l=conectores.value.filter(c=>{const q=busca.value.trim().toLowerCase();return(!q||`${c.nome} ${c.descricao} ${c.categoria}`.toLowerCase().includes(q))&&(categoriaAtiva.value==='todos'||c.categoria===categoriaAtiva.value)&&(!mostrarConectados.value||c.status==='ativo')});if(ordenacao.value==='nome')l.sort((a,b)=>a.nome.localeCompare(b.nome));if(ordenacao.value==='status')l.sort((a,b)=>(b.status==='ativo')-(a.status==='ativo'));return l})
const recursos=[{id:'anuncios',nome:'Publicar anúncios',desc:'Criação e atualização de anúncios.',icon:markRaw(CubeIcon)},{id:'pedidos',nome:'Importar pedidos',desc:'Pedidos centralizados no ERP.',icon:markRaw(ShoppingBagIcon)},{id:'precos',nome:'Sincronizar preços',desc:'Preço por canal e regras comerciais.',icon:markRaw(CurrencyDollarIcon)},{id:'estoque',nome:'Sincronizar estoque',desc:'Saldo por depósito em todos os canais.',icon:markRaw(ArchiveBoxIcon)},{id:'etiquetas',nome:'Emitir etiquetas',desc:'Integração com expedição e transportadoras.',icon:markRaw(TruckIcon)},{id:'fiscal',nome:'NF-e e NFC-e',desc:'Preparação do fluxo fiscal.',icon:markRaw(DocumentTextIcon)},{id:'mensagens',nome:'Mensagens',desc:'Atendimento centralizado.',icon:markRaw(ChatBubbleLeftRightIcon)},{id:'relatorios',nome:'Indicadores',desc:'Vendas, margem e desempenho.',icon:markRaw(ChartBarIcon)}]
const fluxo=[{nome:'Conectar canal',desc:'Cadastre as credenciais da API.',icon:markRaw(Cog6ToothIcon)},{nome:'Sincronizar catálogo',desc:'Produtos, preços e estoque.',icon:markRaw(CubeIcon)},{nome:'Receber pedidos',desc:'Pedidos entram automaticamente.',icon:markRaw(ShoppingBagIcon)},{nome:'Faturar e expedir',desc:'Fiscal, etiqueta e rastreamento.',icon:markRaw(TruckIcon)}]

const categoriaLabel=c=>categoriaNomes[c]||c
const iniciais=n=>String(n||'').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()
const statusTexto=s=>({ativo:'Conectado',pendente:'Configuração salva',inativo:'Inativo',desconectado:'Desconectado',nao_configurado:'Não configurado'})[s]||s
const capacidades=c=>c==='pagamentos'?['Financeiro','Conciliação']:c==='logistica'?['Frete','Etiqueta','Rastreio']:c==='marketing'?['Campanhas','Leads','Conversões']:['Produtos','Pedidos','Estoque']
const imagemFalhou=e=>{e.target.style.display='none'}
const campoProtegido=c=>/(secret|token|password|senha|key)/i.test(c)
function labelCampo(c){const l={seller_id:'Seller ID',client_id:'Client ID',client_secret:'Client Secret',access_token:'Access Token',refresh_token:'Refresh Token',marketplace_id:'Marketplace ID',partner_id:'Partner ID',partner_key:'Partner Key',shop_id:'Shop ID',app_key:'App Key',app_secret:'App Secret',app_id:'App ID',api_key:'API Key',api_secret:'API Secret',api_token:'API Token',store_id:'Store ID',store_url:'URL da loja',consumer_key:'Consumer Key',consumer_secret:'Consumer Secret',merchant_id:'Merchant ID',merchant_key:'Merchant Key',business_id:'Business ID',catalog_id:'Catalog ID',account_id:'Account ID',ad_account_id:'Ad Account ID',customer_id:'Customer ID',developer_token:'Developer Token',public_key:'Public Key',secret_key:'Secret Key',webhook_secret:'Webhook Secret',usuario:'Usuário',senha:'Senha',token:'Token',email:'E-mail',cnpj:'CNPJ',contrato:'Contrato',cartao_postagem:'Cartão de postagem',codigo_acesso:'Código de acesso',codigo_cliente:'Código do cliente',base_url:'URL base',username:'Usuário',tenant:'Tenant'};return l[c]||c.replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase())}
const placeholderCampo=c=>`Informe ${labelCampo(c)}`

async function carregar(){loading.value=true;try{const{data}=await api.get('/marketplaces/catalogo');conectores.value=(data.data||fallback).map(c=>({...c,status:c.status||'nao_configurado'}))}catch(e){conectores.value=fallback;toast.warning('Catálogo local carregado. A API não respondeu.')}finally{loading.value=false}}
function abrir(item){modal.value=item;modalAba.value='acesso';credenciais.value={};mostrarCampos.value={};nomeConta.value=item.nome_conta||''}
function fechar(){modal.value=null;credenciais.value={};nomeConta.value=''}
async function salvar(){processando.value=true;try{const{data}=await api.post(`/marketplaces/${modal.value.tipo}/configurar`,{nome:nomeConta.value||modal.value.nome,status:'pendente',credenciais:credenciais.value,config:{categoria:modal.value.categoria,origem:'hub_omnichannel'}});toast.success(data.message);fechar();await carregar()}catch(e){toast.error(e.response?.data?.message||'Não foi possível salvar a configuração.')}finally{processando.value=false}}
async function testar(item){try{const{data}=await api.get(`/marketplaces/${item.tipo}/testar`);toast[data.ok?'success':'warning'](data.message)}catch(e){toast.error(e.response?.data?.message||'Falha no teste da rota.')}}
async function desconectar(item){if(!item.integracao_id)return;try{const{data}=await api.delete(`/integracoes/${item.integracao_id}`);toast.success(data.message);await carregar()}catch(e){toast.error(e.response?.data?.message||'Não foi possível desconectar.')}}
onMounted(carregar)
</script>

